           public void waitAtConsole() {
               mutex.acquire();
               try {
                   NumArrivals++;
                   if (NumArrivals == 4) {
                       state = CONSOLE_ALLOW;
                       cv.broadcast();
                   } else {
                       while (state != CONSOLE_ALLOW) {
                           cv.wait(mutex);
